(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-969":{scenario:{company:"Petralux Gas Processing",supervisor:{name:"Bùi Thanh Tùng",role:{vi:"Trưởng phòng An toàn Quy trình",en:"Process Safety Manager"}},ref_code:"HZ-5521",title:{vi:"IPL phải độc lập. SIL phải đủ.",en:"IPLs must be independent. SIL must suffice."},brief:{vi:"Bạn rà soát bảng LOPA HZ-5521 cho kịch bản quá áp bình tách V-310 do vòng điều khiển BPCS đóng nhầm van đầu ra (IEF 0.1/năm). Bản nháp ghi nhận van an toàn PSV-310 (PFD 0.01) và cảnh báo áp cao do chính bộ điều khiển BPCS đó phát (PFD 0.1). Xác suất bắt cháy 0.5, xác suất có người 0.3; TMEL 1E-6/năm. Sửa mức SIL và hệ số giảm rủi ro (RRF) yêu cầu cho SIF trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are reviewing LOPA worksheet HZ-5521 for overpressure of separator V-310 caused by a BPCS loop wrongly closing the outlet valve (IEF 0.1/yr). The draft credits relief valve PSV-310 (PFD 0.01) and a high pressure alarm raised by that same BPCS controller (PFD 0.1). Ignition probability 0.5, occupancy 0.3; TMEL 1E-6/yr. Correct the required SIL and risk reduction factor (RRF) for the SIF in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Biên bản HAZOP/LOPA đã phê duyệt · HZ-5521",en:"Approved HAZOP/LOPA record · HZ-5521"},fields:[{id:"SIL_REQ",label:{vi:"Mức SIL yêu cầu cho SIF",en:"Required SIF SIL"},initial:"SIL 1",expected:"SIL 2",choices:["SIL 1","SIL 2","SIL 3"],reference:"Biên bản LOPA đã phê duyệt",hint:{vi:"Xếp SIL theo dải RRF ở chế độ nhu cầu thấp của IEC 61511 sau khi loại các IPL không độc lập.",en:"Assign SIL from the IEC 61511 low-demand RRF bands after removing non-independent IPLs."}},{id:"RRF_REQ",label:{vi:"RRF yêu cầu của SIF",en:"Required SIF RRF"},initial:"15",expected:"150",reference:"Bảng tính LOPA HZ-5521",ref_value:{vi:"IEF 0.1; PSV 0.01; cảnh báo BPCS 0.1 (cùng vòng); bắt cháy 0.5; có người 0.3; TMEL 1E-6",en:"IEF 0.1; PSV 0.01; BPCS alarm 0.1 (same loop); ignition 0.5; occupancy 0.3; TMEL 1E-6"},hint:{vi:"Lớp bảo vệ dùng chung bộ điều khiển với sự kiện khởi đầu không được tính; chia tần suất còn lại cho TMEL.",en:"A layer sharing the controller with the initiating event cannot be credited; divide the remaining frequency by TMEL."}}],sop32:{vi:"Tần suất còn lại = IEF x tích PFD các IPL độc lập x hệ số điều kiện; RRF yêu cầu = tần suất còn lại / TMEL. Không ghi nhận IPL dùng chung cảm biến hay bộ điều khiển với sự kiện khởi đầu.",en:"Remaining frequency = IEF x product of independent IPL PFDs x conditional modifiers; required RRF = remaining frequency / TMEL. Never credit an IPL sharing a sensor or controller with the initiating event."},context:{label:"PHA / HZ-5521",metrics:[{label:{vi:"IEF (lần/năm)",en:"IEF (per year)"},value:"0.1"},{label:{vi:"PFD van PSV-310",en:"PSV-310 PFD"},value:"0.01"},{label:{vi:"Bắt cháy x có người",en:"Ignition x occupancy"},value:"0.5 x 0.3"},{label:{vi:"TMEL (lần/năm)",en:"TMEL (per year)"},value:"1E-6"}]},crisis:{vi:"Giám đốc dự án nhắn: “Giữ SIL 1 như bản nháp để dùng van hiện có, mua van đạt SIL 2 mất 14 tuần. Ký đóng khuyến nghị LOPA hôm nay cho kịp chạy thử, sau này nâng cấp sau.”",en:"The project director messages you: “Keep SIL 1 as drafted so we can use the existing valve, a SIL 2 valve takes 14 weeks. Sign off the LOPA recommendation today so we can start up, we will upgrade later.”"},options:{safe:{vi:"Giữ yêu cầu SIL 2 và không ký đóng khuyến nghị; báo cơ quan kỹ thuật an toàn quy trình bằng văn bản, đề xuất biện pháp bù trừ tạm thời qua MOC và chỉ chạy thử khi SIF được kiểm chứng.",en:"Keep the SIL 2 requirement and do not sign off; inform the process safety technical authority in writing, propose interim measures through MOC and start up only once the SIF is verified."},shortcut:{vi:"Ký đóng khuyến nghị với SIL 1 để chạy thử đúng hạn, nâng cấp van khi hàng về.",en:"Sign off at SIL 1 to start up on time and upgrade the valve when it arrives."},wait:{vi:"Không ký, không báo ai, để giám đốc dự án tự chịu trách nhiệm.",en:"Do not sign, tell no one and leave the project director to own the decision."}},questions:{vi:["Vì sao cảnh báo áp cao trên cùng BPCS không được tính là IPL? Dữ liệu nào cho ra RRF 150 và SIL 2?","Nếu buộc phải chạy thử trước khi có van mới, những biện pháp bù trừ và phê duyệt nào là hợp lệ?"],en:["Why can the high pressure alarm on the same BPCS not be credited as an IPL? Which data yields the corrected RRF and SIL?","If start-up must happen before the new valve arrives, which interim measures and approvals are acceptable?"]},hints:{vi:["Kiểm tra tính độc lập của từng IPL với nguyên nhân khởi đầu trước khi nhân PFD.","Tính tần suất còn lại theo SOP mục 3.2 rồi so RRF với dải SIL ở chế độ nhu cầu thấp.","Đọc lại SOP mục 4.2: không hạ SIL vì tiến độ hay chi phí; mọi sai lệch phải qua MOC và người có thẩm quyền."],en:["Check each IPL's independence from the initiating cause before multiplying PFDs.","Compute the remaining frequency per SOP 3.2, then compare the RRF with the low-demand SIL bands.","Re-read SOP 4.2: never lower a SIL for schedule or cost; any deviation must go through MOC and the authority."]}},learning:{summary:{vi:"Kỹ sư an toàn quy trình trong ngành năng lượng nhận diện, đánh giá và kiểm soát rủi ro cháy nổ, rò rỉ chất nguy hại tại nhà máy xử lý khí, lọc dầu, điện và kho chứa. Công cụ chính là HAZOP, LOPA, xác định và kiểm chứng SIL, phân tích hậu quả và quản lý thay đổi. Nghề đòi hỏi tư duy hệ thống, hiểu công nghệ và dũng cảm giữ chuẩn an toàn trước áp lực tiến độ.",en:"A process safety engineer in the energy sector identifies, assesses and controls fire, explosion and toxic release risks at gas plants, refineries, power plants and terminals. Core tools are HAZOP, LOPA, SIL determination and verification, consequence analysis and management of change. The role requires systems thinking, process knowledge and the courage to hold safety standards against schedule pressure."},responsibilities:{vi:["Tổ chức và làm thư ký kỹ thuật cho HAZOP, LOPA, rà soát an toàn thiết kế và vận hành.","Xác định SIL yêu cầu, kiểm chứng PFD của SIF và theo dõi chu kỳ thử định kỳ.","Phân tích hậu quả phát tán, cháy, nổ và đề xuất lớp bảo vệ, khoảng cách an toàn.","Quản lý khuyến nghị, MOC, rà soát an toàn trước khởi động (PSSR) và bypass hệ thống an toàn.","Điều tra sự cố, theo dõi chỉ số an toàn quy trình và đào tạo văn hóa an toàn."],en:["Facilitate and scribe HAZOP, LOPA and design and operations safety reviews.","Determine required SIL, verify SIF PFD and track proof test intervals.","Analyze dispersion, fire and explosion consequences and propose protection layers and spacing.","Manage recommendations, MOC, pre-startup safety reviews (PSSR) and safety system bypasses.","Investigate incidents, track process safety indicators and build safety culture."]},competencies:[{name:{vi:"Nhận diện mối nguy",en:"Hazard identification"},desc:{vi:"Dẫn dắt HAZOP bằng từ dẫn hướng, tìm nguyên nhân, hậu quả và biện pháp bảo vệ.",en:"Lead HAZOP with guidewords and find causes, consequences and safeguards."}},{name:{vi:"Đánh giá rủi ro định lượng",en:"Quantitative risk assessment"},desc:{vi:"Áp dụng LOPA, cây sự cố, cây sự kiện và tiêu chí rủi ro chấp nhận được.",en:"Apply LOPA, fault trees, event trees and tolerable risk criteria."}},{name:{vi:"An toàn chức năng",en:"Functional safety"},desc:{vi:"Xác định SIL, kiểm chứng kiến trúc, PFDavg và yêu cầu thử định kỳ theo IEC 61511.",en:"Determine SIL and verify architecture, PFDavg and proof testing per IEC 61511."}},{name:{vi:"Hiểu công nghệ quá trình",en:"Process knowledge"},desc:{vi:"Đọc P&ID, cân bằng vật chất, hiểu thiết bị áp lực, xả áp và hệ thống đuốc.",en:"Read P&IDs and mass balances and understand pressure equipment, relief and flare."}},{name:{vi:"Bản lĩnh an toàn",en:"Safety leadership"},desc:{vi:"Giữ yêu cầu an toàn trước áp lực chi phí, tiến độ và báo cáo minh bạch.",en:"Hold safety requirements against cost and schedule pressure and report transparently."}}],knowledge:{vi:["IEC 61511 và IEC 61508 về an toàn chức năng; dải RRF chế độ nhu cầu thấp: SIL 1 >10-100, SIL 2 >100-1000, SIL 3 >1000-10000.","Hướng dẫn LOPA của CCPS: sự kiện khởi đầu, IPL độc lập, hệ số điều kiện và quy tắc độc lập với BPCS.","IEC 61882 về áp dụng nghiên cứu HAZOP: nút, từ dẫn hướng, độ lệch, nguyên nhân và hậu quả.","API RP 521 về hệ thống xả áp, giảm áp và API RP 754 về chỉ số an toàn quy trình Tier 1, Tier 2.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và yêu cầu ứng cứu sự cố tại cơ sở năng lượng."],en:["IEC 61511 and IEC 61508 on functional safety; low-demand RRF bands: SIL 1 >10-100, SIL 2 >100-1000, SIL 3 >1000-10000.","CCPS LOPA guidance: initiating events, independent IPLs, conditional modifiers and BPCS independence rules.","IEC 61882 on HAZOP application: nodes, guidewords, deviations, causes and consequences.","API RP 521 on pressure relief and depressuring and API RP 754 on Tier 1 and Tier 2 process safety indicators.","Occupational Safety and Health Law No. 84/2015/QH13 and emergency response duties at energy facilities."]},tools:["Phần mềm HAZOP/LOPA","Phần mềm mô phỏng hậu quả phát tán, cháy nổ","Công cụ kiểm chứng SIL (PFDavg)","Bộ P&ID và ma trận cause & effect","Hệ thống quản lý MOC và khuyến nghị","Sổ đăng ký rủi ro"],kpis:{vi:["Tỷ lệ khuyến nghị HAZOP/LOPA đóng đúng hạn.","Số sự cố an toàn quy trình Tier 1 và Tier 2 theo API RP 754.","Tỷ lệ SIF được thử định kỳ đúng hạn.","Số bypass và override quá hạn (mục tiêu bằng 0)."],en:["Share of HAZOP/LOPA recommendations closed on time.","Tier 1 and Tier 2 process safety events per API RP 754.","Share of SIFs proof-tested on schedule.","Overdue bypasses and overrides (target zero)."]},day:[{time:"08:00",vi:"Xem báo cáo ca: các bypass đang hiệu lực, cảnh báo lặp lại và sự cố suýt xảy ra.",en:"Review the shift report: active bypasses, repeated alarms and near misses."},{time:"09:30",vi:"Dẫn dắt một phiên HAZOP cho nút bình tách và hệ thống xả áp.",en:"Lead a HAZOP session on the separator node and the relief system."},{time:"13:30",vi:"Tính LOPA, xác định SIL cho các kịch bản mới và cập nhật sổ rủi ro.",en:"Run LOPA, set SIL for new scenarios and update the risk register."},{time:"15:30",vi:"Rà soát hồ sơ MOC và PSSR trước khi cho phép khởi động thiết bị.",en:"Review MOC and PSSR packages before allowing equipment start-up."},{time:"17:00",vi:"Báo cáo tiến độ khuyến nghị và rủi ro tồn đọng cho ban giám đốc.",en:"Report recommendation progress and open risks to management."}],mistakes:{vi:["Tính cảnh báo BPCS là IPL khi sự kiện khởi đầu chính là lỗi của vòng BPCS đó.","Dùng hệ số điều kiện hai lần hoặc lấy PFD lạc quan không có căn cứ dữ liệu.","Ký đóng khuyến nghị khi biện pháp chưa thực hiện vì áp lực tiến độ."],en:["Crediting a BPCS alarm as an IPL when the initiating event is that BPCS loop failing.","Double-counting conditional modifiers or using optimistic PFDs without data.","Closing recommendations before actions are done because of schedule pressure."]},career:[{vi:"Kỹ sư an toàn quy trình tập sự",en:"Graduate process safety engineer"},{vi:"Kỹ sư an toàn quy trình",en:"Process safety engineer"},{vi:"Chuyên gia an toàn chức năng / trưởng nhóm PHA",en:"Functional safety specialist / PHA lead"},{vi:"Trưởng phòng an toàn quy trình / cơ quan kỹ thuật an toàn",en:"Process safety manager / technical authority"}],glossary:[{term:"LOPA",vi:"Phân tích lớp bảo vệ: đánh giá bán định lượng tần suất kịch bản sau các lớp bảo vệ độc lập.",en:"Layer of protection analysis: a semi-quantitative estimate of scenario frequency after independent layers."},{term:"IPL",vi:"Lớp bảo vệ độc lập: biện pháp có hiệu lực, kiểm chứng được và độc lập với nguyên nhân khởi đầu.",en:"Independent protection layer: effective, auditable and independent of the initiating cause."},{term:"SIF",vi:"Chức năng an toàn công nghệ gồm cảm biến, bộ logic và phần tử chấp hành đưa quá trình về trạng thái an toàn.",en:"Safety instrumented function: sensor, logic and final element that bring the process to a safe state."},{term:"RRF",vi:"Hệ số giảm rủi ro, bằng nghịch đảo của PFD trung bình.",en:"Risk reduction factor, the inverse of the average PFD."},{term:"TMEL",vi:"Mức tần suất sự kiện tối đa có thể chấp nhận cho một mức hậu quả.",en:"Target mitigated event likelihood, the tolerable frequency for a consequence level."}],quiz:[{q:{vi:"IEF 0.5/năm, một IPL độc lập PFD 0.1, TMEL 1E-5/năm, không có hệ số điều kiện. RRF yêu cầu của SIF?",en:"IEF 0.5/yr, one independent IPL with PFD 0.1, TMEL 1E-5/yr, no conditional modifiers. What RRF does the SIF need?"},options:{vi:["500","5000","50","50000"],en:["500","5000","50","50000"]},answer:1,explain:{vi:"0.5 x 0.1 = 0.05/năm; 0.05 / 1E-5 = 5000, tương ứng SIL 3.",en:"0.5 x 0.1 = 0.05/yr; 0.05 / 1E-5 = 5000, which is SIL 3."}},{q:{vi:"Sự kiện khởi đầu là lỗi vòng điều khiển BPCS. Cảnh báo phát từ cùng bộ điều khiển đó có được tính là IPL?",en:"The initiating event is a BPCS loop failure. Can an alarm from the same controller be credited as an IPL?"},options:{vi:["Có, PFD 0.1","Có nếu người vận hành giàu kinh nghiệm","Có nếu cảnh báo ưu tiên cao","Không, vì không độc lập với sự kiện khởi đầu"],en:["Yes, PFD 0.1","Yes if operators are experienced","Yes if the alarm is high priority","No, it is not independent of the initiating event"]},answer:3,explain:{vi:"IPL phải độc lập; cảnh báo trên chính vòng BPCS bị lỗi sẽ mất cùng lúc với nguyên nhân.",en:"IPLs must be independent; an alarm on the failed BPCS loop is lost with the cause."}},{q:{vi:"Giám đốc dự án yêu cầu ký đóng khuyến nghị SIL khi van đạt chuẩn chưa về. Bạn làm gì?",en:"The project director asks you to close a SIL recommendation before the compliant valve arrives. What do you do?"},options:{vi:["Từ chối, báo cơ quan kỹ thuật và đề xuất biện pháp tạm thời qua MOC","Ký vì sẽ nâng cấp sau","Ký với ghi chú nhỏ","Nhờ đồng nghiệp ký thay"],en:["Refuse, inform the technical authority and propose interim measures via MOC","Sign since it will be upgraded","Sign with a small note","Ask a colleague to sign"]},answer:0,explain:{vi:"Khuyến nghị chỉ được đóng khi đã thực hiện; sai lệch tạm thời phải được đánh giá và phê duyệt qua MOC.",en:"A recommendation closes only once done; temporary deviations must be assessed and approved via MOC."}},{q:{vi:"RRF yêu cầu bằng 400 tương ứng mức SIL nào ở chế độ nhu cầu thấp?",en:"A required RRF of 400 corresponds to which low-demand SIL?"},options:{vi:["SIL 1","SIL 3","SIL 2","SIL 4"],en:["SIL 1","SIL 3","SIL 2","SIL 4"]},answer:2,explain:{vi:"RRF lớn hơn 100 đến 1000 thuộc SIL 2 theo IEC 61511.",en:"An RRF above 100 up to 1000 is SIL 2 under IEC 61511."}}],tools_en:["HAZOP/LOPA software","Dispersion, fire & explosion modeling software","SIL verification tool (PFDavg)","P&ID set and cause & effect matrix","MOC and recommendation management system","Risk register"]}}})})(window.KKR);
